#define _GNU_SOURCE
#include <ctype.h>
#include <stddef.h>
#include <string.h>
#include <sys/syscall.h>
#include <unistd.h>

/*
 * The audit sandbox exposes a host-PID /proc mount while getpid() returns a
 * nested-namespace PID. Lean 4.22 resolves its executable through
 * /proc/<getpid()>/exe, which therefore does not exist. Redirect only that
 * executable lookup to the namespace-stable /proc/self/exe path.
 */
ssize_t readlink(const char *path, char *buffer, size_t size) {
    const char prefix[] = "/proc/";
    const char suffix[] = "/exe";
    size_t length = strlen(path);
    int is_process_exe =
        length > sizeof(prefix) - 1 + sizeof(suffix) - 1 &&
        strncmp(path, prefix, sizeof(prefix) - 1) == 0 &&
        strcmp(path + length - (sizeof(suffix) - 1), suffix) == 0;
    if (is_process_exe) {
        const char *cursor = path + sizeof(prefix) - 1;
        const char *end = path + length - (sizeof(suffix) - 1);
        while (cursor < end && isdigit((unsigned char)*cursor)) {
            ++cursor;
        }
        is_process_exe = cursor == end;
    }
    return syscall(
        SYS_readlink,
        is_process_exe ? "/proc/self/exe" : path,
        buffer,
        size);
}

